const raw = $input.first().json.body && $input.first().json.body.payload;
const payload = JSON.parse(raw);
let action_id = null;
let action_type = payload.type || null;
let action_value = null;
let channel_id = (payload.channel && payload.channel.id) || null;
let thread_ts = null;
let message_ts = null;
if (payload.type === 'view_submission') {
  const view = payload.view || {};
  action_id = view.callback_id || null;
  action_value = view.state || null;
  channel_id = channel_id || (view.private_metadata || null);
} else {
  const act = (payload.actions && payload.actions[0]) || {};
  action_id = act.action_id || null;
  action_value = (act.selected_option && act.selected_option.value) || act.value || null;
  const msg = payload.message || {};
  thread_ts = msg.thread_ts || msg.ts || null;
  message_ts = msg.ts || null;
}
const threadKey = thread_ts || message_ts || null;
const session_key = channel_id && threadKey ? channel_id + '_' + threadKey : null;
return [{ json: {
  action_id,
  action_type,
  action_value,
  trigger_id: payload.trigger_id || null,
  user_id: (payload.user && payload.user.id) || null,
  user_name: (payload.user && payload.user.username) || null,
  channel_id,
  thread_ts,
  message_ts,
  session_key,
  response_url: payload.response_url || null,
  full_payload: payload
} }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}
var TTL_MS = 30 * 60 * 1000;
function isFresh(row) {
  return !!(row && row.updated_at && (Date.now() - Date.parse(row.updated_at) <= TTL_MS));
}

const WIZARD_STEPS = ['audience_select', 'filters', 'sample_size', 'review_candidates', 'review_email', 'sending', 'complete'];

const p = $input.first().json;
const actionId = p.action_id || '';
const isUxr = typeof actionId === 'string' && actionId.startsWith('uxr_');

const row = getSessionRow();
const fresh = isFresh(row);

let sessionExpired = false;
if (isUxr && p.session_key && !actionId.startsWith('uxr_audience_') && !actionId.startsWith('uxr_cancel') && !fresh) {
  sessionExpired = true;
}

let sessionState = null;
if (fresh) {
  let filters = {};
  try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }
  sessionState = {
    step: row.state,
    audience_type: row.audience || null,
    filters: filters,
    sample_size: row.requested_count || null,
    batch_id: row.batch_id || null,
    calendly_link: row.calendly_link || null,
    email_subject: row.email_subject || null,
    email_body: row.email_body || null
  };
}

return [{ json: {
  ...p,
  is_uxr: isUxr,
  session_expired: sessionExpired,
  session_state: sessionState,
  wizard_steps: WIZARD_STEPS
} }];

const parsed = $('Parse Payload').first().json;
const audienceType = parsed.action_value;
const nowIso = new Date().toISOString();

const nUserFilters = [
  { id: 'cloud_plan', label: 'Cloud plan', coverage: '~95%', warn: false, options: ['Trial', 'n8n cloud Start', 'n8n cloud Pro', 'n8n cloud Enterprise'] },
  { id: 'cloud_plan_status', label: 'Plan status', coverage: '~95%', warn: false, options: ['trialing', 'active', 'past_due', 'canceled'] },
  { id: 'country', label: 'Country', coverage: '~70%', warn: false, type: 'text' },
  { id: 'utm_user_role', label: 'Role at signup', coverage: '~60%', warn: false, options: ['Product & Design', 'Engineering', 'IT / Ops', 'Marketing', 'Sales', 'Founder / C-level', 'Other'] },
  { id: 'company_size', label: 'Company size', coverage: '~25%', warn: true, options: ['Only me', '<20', '20-99', '100-499', '500-999', '1000+'] },
  { id: 'wf_bucket', label: 'Production workflows', coverage: '~12%', warn: true, options: ['1-2', '3-5', '6-20', '21-100', '100+'] },
  { id: 'services_bucket', label: 'Connected services', coverage: '~12%', warn: true, options: ['≤10', '11-20', '21-40', '41-70', '70+'] },
  { id: 'ai_wfs_bucket', label: 'AI workflows', coverage: '~12%', warn: true, options: ['0', '1-2', '3-5', '6-10', '10+'] },
  { id: 'days_bucket', label: 'Account age', coverage: '~12%', warn: true, options: ['<30', '30-180', '180-365', '365-540', '540+'] }
];

const nonUserFilters = [
  { id: 'n8n_usage', label: 'n8n familiarity', coverage: '~100%', warn: false, options: ['aware', 'new', 'explorer'] },
  { id: 'tech_skills', label: 'Technical skills', coverage: '~90%', warn: false, options: ['tech_high', 'tech_mid', 'tech_low', 'tech_none'] },
  { id: 'company_size', label: 'Company size', coverage: '~85%', warn: false, options: ['Only me', '<20', '20-99', '100-499', '500-999', '1000+'] }
];

const filters = audienceType === 'n8n_users' ? nUserFilters : nonUserFilters;
const audienceLabel = audienceType === 'n8n_users' ? 'n8n users' : 'Non-users';

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':busts_in_silhouette: *Audience: ' + audienceLabel + '*\n\nSelect any filters you want to apply. All are optional — skip any you don’t need.' } },
  { type: 'divider' }
];

for (const f of filters) {
  if (f.type === 'text') {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*' + f.label + '* · ' + f.coverage + (f.warn ? ' :warning:' : '') + '\n_Type the country name in the thread after applying other filters, or skip._' } });
  } else {
    const options = f.options.map(o => ({ text: { type: 'plain_text', text: o, emoji: true }, value: o }));
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*' + f.label + '* · ' + f.coverage + (f.warn ? ' :warning:' : '') }, accessory: { type: 'static_select', placeholder: { type: 'plain_text', text: 'Any', emoji: true }, action_id: 'uxr_filter_' + f.id, options: options } });
  }
}

blocks.push({ type: 'divider' });
blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Apply Filters', emoji: true }, style: 'primary', action_id: 'uxr_filter_apply', value: 'apply' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, style: 'danger', action_id: 'uxr_cancel', value: 'cancel' } ] });

return [{ json: {
  channel_id: parsed.channel_id,
  thread_ts: parsed.thread_ts,
  text: 'Filters for ' + audienceLabel,
  blocks: JSON.stringify(blocks),
  sess: {
    session_key: parsed.session_key || '__none__',
    channel: parsed.channel_id || '',
    thread_ts: parsed.thread_ts || '',
    slack_user: parsed.user_id || '',
    state: 'filters',
    audience: audienceType || '',
    filters_json: '{}',
    requested_count: 0,
    batch_id: '',
    email_subject: '',
    email_body: '',
    calendly_link: '',
    last_step_ts: '',
    updated_at: nowIso
  }
} }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}

const parsed = $('Parse Payload').first().json;
const row = getSessionRow();
const nowIso = new Date().toISOString();
if (!row) return [{ json: { skip: true, post_message: false, sess: { session_key: '__none__', state: '', filters_json: '{}', updated_at: nowIso } } }];

let filters = {};
try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }

const actionId = parsed.action_id;
if (actionId === 'uxr_filter_apply') {
  const filterEntries = Object.entries(filters);
  const filterSummary = filterEntries.length > 0
    ? filterEntries.map(([k, v]) => '• *' + k + '*: ' + v).join('\n')
    : '_No filters applied — sampling from the full pool._';

  const audienceLabel = row.audience === 'n8n_users' ? 'n8n users' : 'Non-users';

  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: ':1234: *How many people do you want to contact?*\n\n*Audience:* ' + audienceLabel + '\n*Filters:*\n' + filterSummary } },
    { type: 'input', block_id: 'sample_size_block', element: { type: 'number_input', is_decimal_allowed: false, action_id: 'uxr_sample_size_input', min_value: '1', max_value: '20', placeholder: { type: 'plain_text', text: 'e.g. 10' } }, label: { type: 'plain_text', text: 'Number of people to contact (1-20)' } },
    { type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Draw Sample', emoji: true }, style: 'primary', action_id: 'uxr_sample_draw', value: 'draw' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, style: 'danger', action_id: 'uxr_cancel', value: 'cancel' } ] }
  ];

  return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'How many people do you want to contact?', blocks: JSON.stringify(blocks), post_message: true, sess: { session_key: row.session_key, state: 'sample_size', filters_json: JSON.stringify(filters), updated_at: nowIso } } }];
} else {
  const filterId = actionId.replace('uxr_filter_', '');
  filters[filterId] = parsed.action_value;
  return [{ json: { skip: true, stored_filter: filterId, value: parsed.action_value, post_message: false, sess: { session_key: row.session_key, state: row.state, filters_json: JSON.stringify(filters), updated_at: nowIso } } }];
}

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}

const parsed = $('Parse Payload').first().json;
const row = getSessionRow();
const nowIso = new Date().toISOString();
const expiredBlocks = [{ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: This recruiting session is no longer active. Please start a new one by asking Darwin to recruit participants.' } }];
if (!row) return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'Session no longer active.', blocks: JSON.stringify(expiredBlocks), candidates: [], batch_id: '', sess: { session_key: '__none__', state: '', requested_count: 0, batch_id: '', updated_at: nowIso } } }];

let sampleSize = NaN;
try {
  const payload = typeof parsed.full_payload === 'string' ? JSON.parse(parsed.full_payload) : parsed.full_payload;
  const block = payload && payload.state && payload.state.values && payload.state.values.sample_size_block;
  if (block) {
    if (block.uxr_sample_size_input && block.uxr_sample_size_input.value != null) {
      sampleSize = parseInt(block.uxr_sample_size_input.value, 10);
    } else if (block.uxr_sample_size_select && block.uxr_sample_size_select.selected_option) {
      sampleSize = parseInt(block.uxr_sample_size_select.selected_option.value, 10);
    }
  }
} catch (e) {}
if (!Number.isFinite(sampleSize)) sampleSize = row.requested_count || 5;
if (!Number.isFinite(sampleSize) || sampleSize < 1) sampleSize = 5;
if (sampleSize > 20) sampleSize = 20;

const batchId = 'batch_' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);

const mockDomains = ['acme.com', 'globex.io', 'initech.co', 'umbrella.dev', 'wayne.tech', 'stark.io', 'oscorp.net', 'lexcorp.com'];
const mockRoles = ['Engineering', 'Product & Design', 'IT / Ops', 'Marketing', 'Founder / C-level'];
const mockPlans = ['n8n cloud Start', 'n8n cloud Pro', 'Trial'];
const mockCountries = ['US', 'Germany', 'UK', 'Brazil', 'India'];
const mockCandidates = [];
for (let i = 0; i < sampleSize; i++) {
  const email = 'user' + (i + 1) + '@' + mockDomains[i % mockDomains.length];
  const plan = mockPlans[i % mockPlans.length];
  const role = mockRoles[i % mockRoles.length];
  const country = mockCountries[i % 5];
  mockCandidates.push({ email: email, first_name: 'user' + (i + 1), plan: plan, role: role, country: country, summary: plan + ' · ' + role + ' · ' + country });
}

const audienceLabel = row.audience === 'n8n_users' ? 'n8n users' : 'Non-users';
let filters = {};
try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }
const filterEntries = Object.entries(filters);
const candidateList = mockCandidates.map((c, i) => (i + 1) + '. `' + c.email + '` · ' + c.plan + ' · ' + c.role + ' · ' + c.country).join('\n');

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':clipboard: *Candidate List* (' + sampleSize + ' people)\n\n*Audience:* ' + audienceLabel + '\n*Filters:* ' + (filterEntries.length > 0 ? filterEntries.map(([k, v]) => k + '=' + v).join(', ') : 'none') + '\n\n:warning: _Phase 1: These are mock candidates. Real Customer.io search coming in Phase 2._' } },
  { type: 'section', text: { type: 'mrkdwn', text: candidateList } },
  { type: 'divider' },
  { type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Approve List', emoji: true }, style: 'primary', action_id: 'uxr_approve_list_yes', value: 'approve' }, { type: 'button', text: { type: 'plain_text', text: ':arrows_counterclockwise: New Sample', emoji: true }, action_id: 'uxr_sample_redraw', value: 'redraw' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, style: 'danger', action_id: 'uxr_cancel', value: 'cancel' } ] }
];

return [{ json: {
  channel_id: parsed.channel_id,
  thread_ts: parsed.thread_ts,
  text: 'Candidate list (' + sampleSize + ' people)',
  blocks: JSON.stringify(blocks),
  candidates: mockCandidates,
  batch_id: batchId,
  sess: { session_key: row.session_key, state: 'review_candidates', requested_count: sampleSize, batch_id: batchId, updated_at: nowIso }
} }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}

const parsed = $('Parse Payload').first().json;
const row = getSessionRow();
const nowIso = new Date().toISOString();
const expiredBlocks = [{ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: This recruiting session is no longer active. Please start a new one by asking Darwin to recruit participants.' } }];
if (!row) return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'Session no longer active.', blocks: JSON.stringify(expiredBlocks), sess: { session_key: '__none__', state: '', email_subject: '', email_body: '', updated_at: nowIso } } }];

const emailSubject = 'Invitation: Help us improve n8n';
const emailBody = 'Hi there, 👋\n\nWe’re running quick research sessions to understand how you work and what would make your experience better.\n\nWhat’s involved:\n• A 30-minute video chat (recorded for internal notes)\n• Screen share to show us around your n8n instance\n• $50 gift card as a thank you\n• The interview will be conducted in English\n\nInterested?\nPick a time that works for you: {{calendly_link}}\n\nThank you!';

const candidateCount = row.requested_count || 0;

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':email: *Email Preview*\n\nThis email will be sent to *' + candidateCount + ' people*. Review and approve, or edit before sending.' } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: '*Subject:* ' + emailSubject + '\n\n' + emailBody.replace('{{calendly_link}}', '_[Calendly link will be inserted]_') } },
  { type: 'divider' },
  { type: 'input', block_id: 'calendly_block', element: { type: 'url_text_input', action_id: 'uxr_email_calendly_url', placeholder: { type: 'plain_text', text: 'https://calendly.com/your-link' } }, label: { type: 'plain_text', text: 'Your Calendly booking URL' } },
  { type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: ':white_check_mark: Approve & Send', emoji: true }, style: 'primary', action_id: 'uxr_send_approve', value: 'send' }, { type: 'button', text: { type: 'plain_text', text: ':pencil: Edit Email', emoji: true }, action_id: 'uxr_email_edit', value: 'edit' }, { type: 'button', text: { type: 'plain_text', text: 'Cancel', emoji: true }, style: 'danger', action_id: 'uxr_cancel', value: 'cancel' } ] }
];

return [{ json: {
  channel_id: parsed.channel_id,
  thread_ts: parsed.thread_ts,
  text: 'Email preview — review and approve',
  blocks: JSON.stringify(blocks),
  sess: { session_key: row.session_key, state: 'review_email', email_subject: emailSubject, email_body: emailBody, updated_at: nowIso }
} }];

const parsed = $('Parse Payload').first().json;
const blocks = [ { type: 'section', text: { type: 'mrkdwn', text: ':construction: *Email editing coming soon*\n\nFor now, you can approve the default template or cancel and start over. The buttons on the email preview above still work.' } } ];
return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'Email editing coming soon', blocks: JSON.stringify(blocks) } }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}

const parsed = $('Parse Payload').first().json;
const row = getSessionRow();
const nowIso = new Date().toISOString();
const expiredBlocks = [{ type: 'section', text: { type: 'mrkdwn', text: ':hourglass: This recruiting session is no longer active. Please start a new one by asking Darwin to recruit participants.' } }];
if (!row) return [{ json: { channel_id: parsed.channel_id, thread_ts: parsed.thread_ts, text: 'Session no longer active.', blocks: JSON.stringify(expiredBlocks), sess: { session_key: '__none__', state: '', calendly_link: '', updated_at: nowIso } } }];

let calendlyUrl = '';
try {
  const payload = typeof parsed.full_payload === 'string' ? JSON.parse(parsed.full_payload) : parsed.full_payload;
  const url = payload && payload.state && payload.state.values && payload.state.values.calendly_block && payload.state.values.calendly_block.uxr_email_calendly_url && payload.state.values.calendly_block.uxr_email_calendly_url.value;
  if (url) calendlyUrl = url;
} catch (e) {}
const calendlyDisplay = calendlyUrl || '(not provided — the real send will refuse to run without it)';

const candidateRows = $('Load Batch Candidates').all().map(i => i.json).filter(r => r && r.email);
const candidateCount = candidateRows.length || row.requested_count || 0;
const audienceLabel = row.audience === 'n8n_users' ? 'n8n users' : 'Non-users';
let filters = {};
try { filters = JSON.parse(row.filters_json || '{}'); } catch (e) { filters = {}; }
const filterEntries = Object.entries(filters);
const filterSummary = filterEntries.length > 0 ? filterEntries.map(([k, v]) => k + '=' + v).join(', ') : 'none';
const emailList = candidateRows.length > 0 ? candidateRows.map((c, i) => (i + 1) + '. `' + c.email + '`').join('\n') : '_(no staged candidates found for this batch)_';

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':white_check_mark: *Recruiting Complete!*\n\n:warning: _Phase 1: No emails were actually sent. This is a simulation._\n\n*Summary:*\n• *Audience:* ' + audienceLabel + '\n• *Filters:* ' + filterSummary + '\n• *Candidates:* ' + candidateCount + '\n• *Calendly:* ' + calendlyDisplay + '\n• *Status:* Simulated send (Phase 1)' } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: '*Would have emailed:*\n' + emailList } },
  { type: 'context', elements: [ { type: 'mrkdwn', text: ':information_source: The real send goes through the UXR Send & Stamp workflow (Mailgun + Customer.io stamp) once its credentials are in place.' } ] }
];

return [{ json: {
  channel_id: parsed.channel_id,
  thread_ts: parsed.thread_ts,
  text: 'Recruiting complete — ' + candidateCount + ' candidates (simulated)',
  blocks: JSON.stringify(blocks),
  sess: { session_key: row.session_key, state: 'complete', calendly_link: calendlyUrl, updated_at: nowIso }
} }];

const p = $('Parse Payload').first().json;
const actionId = p.action_id || '';
const fullPayload = typeof p.full_payload === 'string' ? JSON.parse(p.full_payload) : (p.full_payload || {});
const message = fullPayload.message || {};
const originalBlocks = Array.isArray(message.blocks) ? message.blocks : [];

const CONFIRMATION_MAP = {
  'uxr_audience_n8n_users': '✅ Audience: n8n users',
  'uxr_audience_non_users': '✅ Audience: Non-users',
  'uxr_filter_apply': '✅ Filters applied',
  'uxr_filter_skip': '✅ No filters applied',
  'uxr_sample_draw': '✅ Drawing sample...',
  'uxr_approve_list_yes': '✅ Candidate list approved',
  'uxr_approve_list_no': '✅ Candidate list rejected — redrawing',
  'uxr_email_approve': '✅ Email approved',
  'uxr_send_approve': '✅ Sending invitations...'
};

function isFreezeAction(id) {
  if (id.startsWith('uxr_audience_')) return true;
  if (id === 'uxr_filter_apply' || id === 'uxr_filter_skip') return true;
  if (id === 'uxr_sample_draw') return true;
  if (id.startsWith('uxr_approve_list_')) return true;
  if (id.startsWith('uxr_email_')) return id !== 'uxr_email_edit';
  if (id.startsWith('uxr_send_')) return true;
  return false;
}

const shouldFreeze = isFreezeAction(actionId) && originalBlocks.length > 0 && !!p.message_ts;

let confirmationText = CONFIRMATION_MAP[actionId];
if (!confirmationText) confirmationText = '✅ Selection confirmed';

const keepTypes = ['section', 'header', 'context', 'divider'];
const frozenBlocks = originalBlocks.filter(b => b && keepTypes.includes(b.type));
frozenBlocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: confirmationText }] });

return [{ json: {
  ...p,
  shouldFreeze,
  frozenBlocks,
  confirmationText,
  message_ts: p.message_ts,
  channel_id: p.channel_id
} }];

function getSessionRow() {
  var items = $('Load Session').all();
  if (!items.length) return null;
  var r = items[0].json || {};
  return r.session_key ? r : null;
}
var TTL_MS = 30 * 60 * 1000;
function isFresh(row) {
  return !!(row && row.updated_at && (Date.now() - Date.parse(row.updated_at) <= TTL_MS));
}

const p = $('Freeze Clicked Message').first().json;
const actionId = p.action_id || '';

const STEP_ACTION_MAP = {
  'uxr_audience_': 'audience_select',
  'uxr_filter_apply': 'filters',
  'uxr_filter_skip': 'filters',
  'uxr_sample_draw': 'sample_size',
  'uxr_sample_redraw': 'review_candidates',
  'uxr_approve_list_yes': 'review_candidates',
  'uxr_approve_list_no': 'review_candidates',
  'uxr_email_approve': 'review_email',
  'uxr_email_edit': 'review_email',
  'uxr_send_approve': 'review_email'
};

const row = getSessionRow();
const fresh = isFresh(row);
const currentStep = fresh ? row.state : null;

let stepValid;
let expectedStep = null;

if (actionId.startsWith('uxr_cancel')) {
  stepValid = true;
} else if (actionId.startsWith('uxr_audience_')) {
  stepValid = true;
  expectedStep = 'audience_select';
} else if (!fresh) {
  stepValid = true;
} else {
  let matchedPrefix = null;
  for (const key of Object.keys(STEP_ACTION_MAP)) {
    if (actionId === key || actionId.startsWith(key)) {
      if (matchedPrefix === null || key.length > matchedPrefix.length) matchedPrefix = key;
    }
  }
  if (matchedPrefix) {
    expectedStep = STEP_ACTION_MAP[matchedPrefix];
    stepValid = currentStep === expectedStep;
  } else {
    stepValid = true;
  }
}

return [{ json: {
  ...p,
  step_valid: stepValid,
  current_step: currentStep,
  expected_step: expectedStep
} }];

